import React from "react";
import { CheckCircle, Key, Shuffle, Lock, UploadCloud } from "lucide-react";

const CryptoFlow = ({ currentStep = 0, mode = "hybrid" }) => {

  // ================= HYBRID STEPS =================
  const hybridSteps = [
    {
      label: "Ephemeral Agreement",
      sub: "X25519",
      details: ["Generate ephemeral key", "Exchange public values"]
    },
    {
      label: "Encapsulate Secret",
      sub: "Shared Secret",
      details: ["Compute secret", "Create ciphertext"]
    },
    {
      label: "HKDF Derivation",
      sub: "SHA-256",
      details: ["Mix salt", "Expand to AES key"]
    },
    {
      label: "Encrypt Payload",
      sub: "AES-256-GCM",
      details: ["Encrypt blocks", "Generate tag"]
    },
    {
      label: "Upload to Cloud",
      sub: "Untrusted",
      details: ["Pack blob", "Push storage"]
    }
  ];

  // ================= RSA STEPS =================
  const rsaSteps = [
    {
      label: "Generate Keypair",
      sub: "RSA-2048",
      details: ["Create public key", "Create private key"]
    },
    {
      label: "Encrypt Session Key",
      sub: "PKCS#1",
      details: ["Wrap AES key", "Prepare envelope"]
    },
    {
      label: "AES Derivation",
      sub: "Standard KDF",
      details: ["Prepare symmetric key"]
    },
    {
      label: "Encrypt Payload",
      sub: "AES-GCM",
      details: ["Encrypt blocks", "Generate tag"]
    },
    {
      label: "Upload to Cloud",
      sub: "Untrusted",
      details: ["Pack blob", "Push storage"]
    }
  ];

  const steps = mode === "hybrid" ? hybridSteps : rsaSteps;

  const activeColor =
    mode === "hybrid"
      ? "text-neon-green border-neon-green"
      : "text-purple-400 border-purple-400";

  const lineColor =
    mode === "hybrid"
      ? "bg-neon-green"
      : "bg-purple-500";

  return (
    <div className="bg-black/40 p-6 rounded-lg border border-scifi-border mb-6">
      <div className="flex justify-between items-start relative">

        {/* BASE LINE */}
        <div className="absolute top-6 left-0 w-full h-1 bg-gray-800"></div>

        {/* PROGRESS LINE */}
        <div
          className={`absolute top-6 left-0 h-1 transition-all duration-500 ${lineColor}`}
          style={{
            width: `${(Math.max(currentStep - 1, 0) / (steps.length - 1)) * 100}%`
          }}
        ></div>

        {steps.map((step, index) => {
          const isActive = currentStep >= index + 1;
          const isCurrent = currentStep === index + 1;

          return (
            <div key={index} className="relative z-10 flex flex-col items-center w-32">

              {/* NODE */}
              <div
                className={`w-12 h-12 rounded-full flex items-center justify-center border-2 bg-black
                ${isActive ? activeColor : "border-gray-700 text-gray-700"}`}
              >
                {isActive && !isCurrent ? (
                  <CheckCircle size={20} />
                ) : (
                  <Key size={18} />
                )}
              </div>

              {/* TITLE */}
              <div className="mt-3 text-center">
                <p className={`text-[10px] font-bold uppercase ${isActive ? "text-white" : "text-gray-600"}`}>
                  {step.label}
                </p>
                <p className="text-[9px] text-gray-500 font-mono">
                  {step.sub}
                </p>
              </div>

              {/* DETAILS */}
              <div className="mt-3 text-[10px] font-mono text-neon-green space-y-1">
                {step.details.map((d, i) => (
                  <p key={i}>{d}</p>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default CryptoFlow;
